gold.original_css:
:root {
  /* Base roles */
  --color-primary: #daa520;   
  --color-primary-bright: #ffd700;
  --color-secondary: #3c5a7a; /* Steel Blue */

  --color-text-light: #c0c0c0;
  --color-text-accent: #9cf;

  --color-danger: #ff4444;
  --color-danger-dark: #7a3c3c;

  --color-bg-dark: #2c3e50;
  --color-background: rgba(0, 0, 0, 0.3);
  --color-black: #000;
  --color-xpbarbg: #2c2c30;
  --color-frosted:rgba(40,45,55,0.55);
  --color-evenrow: #181818;
  --color-oddrow: #23231b;

  --button-disabled-border-color: #333;
  --button-disabled-color: #666;

  --button-standard: #ffd700;
  --button-standard-hover-bg: #444;
  --button-standard-hover-border: #ffd700;

  --button-delete: #f04848;
  --button-delete-hover-bg: #e74c3c;
  --button-delete-hover-border: #ff0000;
  --button-delete-hover-color: #000;

  --button-edit: #2196f3;
  --button-edit-hover-bg: #2196f3;
  --button-edit-hover-border: #004a86;
  --button-edit-hover-color: #000;

  --button-save: #2fa52b;
  --button-save-hover-bg: #2fa52b;
  --button-save-hover-border: #84ff80;
  --button-save-hover-color: #000;

  --button-buy: #2fa52b;
  --button-buy-hover-bg: #2fa52b;
  --button-buy-hover-border: #84ff80;
  --button-buy-hover-color: #000;

  --button-pager-bg: #222;
  --button-pager-color: #ffd700;
  --button-pager-border: #ffd700;
  --button-pager-hover-bg: #444;
  --button-pager-hover-border: #ffd700;
}
/* --- Text Color Utilities for Descriptions --- */
.text-green { color: #2ecc71; font-weight: bold; }
.text-red { color: #e74c3c; font-weight: bold; }
.text-blue { color: #3498db; font-weight: bold; }
.text-gold { color: #ffd700; font-weight: bold; }
.text-darkgold { color: #daa520; font-weight: bold; }
.text-white { color: #c0c0c0; font-weight: bold; }

/* Value colors */
.pos{ color:#6ddc8b !important; font-weight:700; }
.neg{ color:#ff8a8a !important; font-weight:700; }
.focus{ color:#9d7dff; font-weight:700; }
.credits { color: #ffd700 !important; font-weight: 700; }

steel.original_css:
:root {
  --btn-bg: #2c3e50; 
  --btn-border: #3c5a7a;

  --btn-standard-color: #9cf; /* light blue text */
  --btn-standard-hover-bg: #3c5a7a; /* steel blue border tone */
  --btn-standard-hover-border: #9cf;

  --btn-pager-bg: #222;
  --btn-pager-color: #9cf;
  --btn-pager-border: #3c5a7a;
  --btn-pager-hover-bg: #3c5a7a;
  --btn-pager-hover-border: #9cf;

  --btn-delete-color: #ff8a8a; /* lighter red to match bluesteel scheme */
  --btn-delete-hover-bg: #7a3c3c;
  --btn-delete-hover-border: #ff4444;
  --btn-delete-hover-color: #000;

  --btn-edit-color: #3c5a7a; /* steel blue */
  --btn-edit-hover-bg: #9cf;
  --btn-edit-hover-border: #3c5a7a;
  --btn-edit-hover-color: #000;

  --btn-save-color: #2fa52b; /* green remains green */
  --btn-save-hover-bg: #2fa52b;
  --btn-save-hover-border: #84ff80;
  --btn-save-hover-color: #000;

  --btn-buy-color: #2fa52b;
  --btn-buy-hover-bg: #2fa52b;
  --btn-buy-hover-border: #84ff80;
  --btn-buy-hover-color: #000;
}

